/* Extracted established native layout policy; generated by extract_layout_engine.py. */
static void *g_dif_changed; /* card field we laid out for 4-deck, or NULL; message thread */
static void dif_restore(void) {
    char *dif = g_dif_changed;
    g_dif_changed = NULL;
    if (!ptr_ok(dif) || *(uintptr_t *) dif != DIF_VT)
        return;
    for (int i = 0; i < 4; i++) {
        void *c = *(void **) (dif + DIF_CARD0 + 8 * i);
        if (is_class(c, "N3gui8waveform14DeckInfoWidgetE"))
            comp_bounds(as_component(c), 5, (i & 1) ? 191 : 11, 140, 170);
    }
    comp_size(dif, 156, 388);
    layout_components.stock_cards(dif);
    olog("layout: card field back to stock\n");
}

/* The WaveformView's MixerAreaWidget (mic, channel, Beat FX and FX channel select parts),
 * found by class among the view's children; NULL if absent. */
static char *view_mixer(char *view_comp) {
    char **kids = *(char ***) (view_comp + 0x40);
    int n = *(int *) (view_comp + 0x50);
    if (!ptr_ok(kids) || n < 0 || n > 64)
        return NULL;
    for (int i = 0; i < n; i++)
        if (is_class(kids[i], "N3gui5mixer15MixerAreaWidgetE"))
            return kids[i];
    return NULL;
}

/* 4-deck hides the mixer's mic, channel and Beat FX parts and keeps the FX channel select
 * row. Only parts EP136 had visible are hidden, and only those are shown again. The mixer
 * paints its strip's background, so it is also shrunk to the row (EP136's bounds put back). */
static char *child_of_class(char *c, const char *name, size_t prefix);
static void fx_sidebar_restore(void);
static void fx_overlay_restore(void);
#define FXSEL_CLASS "N3gui5mixer21FxChannelSelectWidgetE"
static int g_mixer_box[4], g_fxsel_box[4];
static const char *const mixer_hide[] = {"N3gui5mixer13MicAreaWidgetE", "N3gui5mixer13ChannelWidgetE"};
static char *g_mixer_hidden;   /* mixer we changed for 4-deck, or NULL; message thread */
static char *g_mixer_parts[8]; /* the parts we hid */
static int is_mixer_hide(const char *c) {
    const char *k = rtti_name(c);
    for (size_t j = 0; k && j < sizeof mixer_hide / sizeof *mixer_hide; j++)
        if (!strcmp(k, mixer_hide[j]))
            return 1;
    return 0;
}
static void mixer_restore(void) {
    fx_sidebar_restore();
    fx_overlay_restore();
    char *m = g_mixer_hidden;
    g_mixer_hidden = NULL;
    for (int i = 0; i < 8; i++) {
        char *c = g_mixer_parts[i];
        g_mixer_parts[i] = NULL;
        if (is_class(m, "N3gui5mixer15MixerAreaWidgetE") && is_mixer_hide(c) && *(char **) (c + COMP_PARENT) == m)
            comp_visible(c, 1);
    }
    if (is_class(m, "N3gui5mixer15MixerAreaWidgetE")) {
        const int *b = g_mixer_box;
        comp_bounds(m, b[0], b[1], b[2], b[3]);
        char *fx = child_of_class(m, FXSEL_CLASS, 0);
        if (fx)
            comp_bounds(fx, g_fxsel_box[0], g_fxsel_box[1], g_fxsel_box[2], g_fxsel_box[3]);
        olog("layout: mixer strip back\n");
    }
}
static void mixer_converge(char *m, int first) {
    char *fx = child_of_class(m, FXSEL_CLASS, 0);
    if (!fx)
        return;
    if (first) {
        memcpy(g_mixer_box, m + COMP_BOUNDS, sizeof g_mixer_box);
        memcpy(g_fxsel_box, fx + COMP_BOUNDS, sizeof g_fxsel_box);
    }
    const int *fb = g_fxsel_box;
    comp_bounds(m, g_mixer_box[0] + fb[0], g_mixer_box[1] + fb[1], fb[2], fb[3]);
    comp_bounds(fx, 0, 0, fb[2], fb[3]);
    char **kids = *(char ***) (m + 0x40);
    int n = *(int *) (m + 0x50);
    if (!ptr_ok(kids) || n < 0 || n > 64)
        return;
    for (int i = 0; i < n; i++) {
        if (!is_mixer_hide(kids[i]) || !comp_visible_now(kids[i]))
            continue;
        for (int j = 0; j < 8; j++)
            if (!g_mixer_parts[j] || g_mixer_parts[j] == kids[i]) {
                g_mixer_parts[j] = kids[i];
                comp_visible(kids[i], 0);
                break;
            }
    }
}

static char *child_of_class(char *c, const char *name, size_t prefix) {
    char **kids = *(char ***) (c + 0x40);
    int n = *(int *) (c + 0x50);
    if (!ptr_ok(kids) || n < 0 || n > 64)
        return NULL;
    for (int i = 0; i < n; i++) {
        const char *k = rtti_name(kids[i]);
        if (k && (prefix ? !strncmp(k, name, prefix) : !strcmp(k, name)))
            return kids[i];
    }
    return NULL;
}

